def _daily_valid_mask(
    quality: pd.DataFrame,
    criteria: dict[str, Any],
) -> pd.Series:
    return (
        quality["candle_coverage"].ge(criteria["min_avg_candle_coverage"])
        & quality["valid_intraday_returns"].ge(
            criteria["min_intraday_returns_per_day"]
        )
        & quality["all_prices_positive"].fillna(False)
    )


def evaluate_sample_quality(
    quality: pd.DataFrame,
    synchronized: pd.DataFrame,
    config: dict[str, Any],
    download_status: pd.DataFrame | None = None,
) -> pd.DataFrame:
    """Produz uma linha de cobertura e decisao por ticker configurado."""
    criteria = config["sample_selection"]
    groups = ticker_groups(config)
    quality = quality.copy()
    quality["date"] = pd.to_datetime(quality["date"], errors="coerce")
    quality["day_valid"] = _daily_valid_mask(quality, criteria)

    download_lookup: dict[str, dict[str, Any]] = {}
    if download_status is not None and not download_status.empty:
        download_lookup = download_status.set_index("ticker").to_dict("index")

    rows: list[dict[str, Any]] = []
    for ticker in configured_tickers(config):
        ticker_quality = quality.loc[quality["ticker"].eq(ticker)].copy()
        ticker_data = synchronized.loc[synchronized["ticker"].eq(ticker)]
        download_info = download_lookup.get(ticker, {})

        if ticker_quality.empty:
            reason = download_info.get("error") or "sem dados intradiarios validos"
            rows.append(
                {
                    "ticker": ticker,
                    "grupo": groups[ticker],
                    "primeiro_dia": pd.NaT,
                    "ultimo_dia": pd.NaT,
                    "numero_dias": 0,
                    "numero_dias_validos": 0,
                    "numero_observacoes_intradiarias": 0,
                    "observacoes_medias_por_dia": 0.0,
                    "cobertura_media_candles": 0.0,
                    "proporcao_precos_parados": np.nan,
                    "positive_volume_share": 0.0,
                    "dias_removidos_falta_dados": 0,
                    "status": "excluded",
                    "razao_exclusao": reason,
                }
            )
            continue

        valid_days = int(ticker_quality["day_valid"].sum())
        total_days = int(len(ticker_quality))
        avg_coverage = float(ticker_quality["candle_coverage"].mean())
        avg_observations = float(ticker_quality["observed_candles"].mean())
        stale_share = float(
            ticker_data["log_return"].dropna().eq(0).mean()
        )
        volume_share = float(ticker_quality["positive_volume_share"].mean())
        all_positive = bool(ticker_quality["all_prices_positive"].all())

        reasons: list[str] = []
        if valid_days < criteria["min_valid_days"]:
            reasons.append(
                f"dias validos {valid_days} < {criteria['min_valid_days']}"
            )
        if avg_coverage < criteria["min_avg_candle_coverage"]:
            reasons.append(
                f"cobertura media {avg_coverage:.1%} abaixo do minimo"
            )
        if stale_share > criteria["max_stale_price_share"]:
            reasons.append(
                f"precos parados {stale_share:.1%} acima do maximo"
            )
        if volume_share < criteria.get("min_positive_volume_share", 0.0):
            reasons.append(
                f"volume positivo {volume_share:.1%} abaixo do minimo"
            )
        if criteria.get("require_positive_prices", True) and not all_positive:
            reasons.append("precos nao positivos")
        if download_info.get("status") == "unavailable":
            reasons.append(download_info.get("error") or "falha grave no download")

        rows.append(
            {
                "ticker": ticker,
                "grupo": groups[ticker],
                "primeiro_dia": ticker_quality["date"].min(),
                "ultimo_dia": ticker_quality["date"].max(),
                "numero_dias": total_days,
                "numero_dias_validos": valid_days,
                "numero_observacoes_intradiarias": int(
                    ticker_quality["observed_candles"].sum()
                ),
                "observacoes_medias_por_dia": avg_observations,
                "cobertura_media_candles": avg_coverage,
                "proporcao_precos_parados": stale_share,
                "positive_volume_share": volume_share,
                "dias_removidos_falta_dados": total_days - valid_days,
                "status": "included" if not reasons else "excluded",
                "razao_exclusao": "; ".join(reasons),
            }
        )
    return pd.DataFrame(rows)


def run_sample_selection(
    config: dict[str, Any] | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Seleciona tickers e dias, gerando a base processada."""
    config = config or load_config()
    interim_dir = PROJECT_ROOT / "data" / "interim"
    synchronized = pd.read_csv(
        interim_dir / "intraday_synchronized.csv",
        parse_dates=["datetime", "date"],
    )
    quality = pd.read_csv(
        interim_dir / "daily_data_quality.csv",
        parse_dates=["date"],
    )
    status_path = PROJECT_ROOT / "data" / "raw" / "download_status.csv"
    download_status = pd.read_csv(status_path) if status_path.exists() else None

    coverage = evaluate_sample_quality(
        quality, synchronized, config, download_status
    )
    included = coverage.loc[coverage["status"].eq("included"), "ticker"].tolist()
    criteria = config["sample_selection"]
    quality["day_valid"] = _daily_valid_mask(quality, criteria)
    valid_pairs = quality.loc[quality["day_valid"], ["ticker", "date"]].copy()
    valid_pairs["date_key"] = valid_pairs["date"].dt.strftime("%Y-%m-%d")

    synchronized["date_key"] = pd.to_datetime(
        synchronized["date"], errors="coerce"
    ).dt.strftime("%Y-%m-%d")
    selected = synchronized.loc[synchronized["ticker"].isin(included)].merge(
        valid_pairs[["ticker", "date_key"]],
        on=["ticker", "date_key"],
        how="inner",
    )
    selected = selected.drop(columns=["date_key"]).sort_values(
        ["ticker", "datetime"]
    )

    daily_prices = (
        selected.sort_values("datetime")
        .groupby(["ticker", "date"], as_index=False)
        .agg(
            daily_close=("close", "last"),
            intraday_observations=("log_return", "count"),
        )
        .sort_values(["ticker", "date"])
    )
    daily_prices["daily_log_return"] = daily_prices.groupby("ticker")[
        "daily_close"
    ].transform(lambda values: np.log(values).diff())
    daily_prices["daily_return_pct"] = 100 * daily_prices["daily_log_return"]

    processed_dir = PROJECT_ROOT / "data" / "processed"
    tables_dir = PROJECT_ROOT / "outputs" / "tables"
    save_csv(selected, processed_dir / "intraday_returns.csv")
    save_csv(daily_prices, processed_dir / "daily_prices_returns.csv")
    save_csv(coverage, tables_dir / "data_coverage_by_ticker.csv")
    save_csv(
        coverage.loc[coverage["status"].eq("excluded")].rename(
            columns={
                "grupo": "group",
                "razao_exclusao": "motivo_exclusao",
                "cobertura_media_candles": "cobertura",
                "numero_dias_validos": "dias_validos",
                "observacoes_medias_por_dia": "observacoes_medias",
                "proporcao_precos_parados": "proporcao_preco_parado",
            }
        )[
            [
                "ticker",
                "group",
                "motivo_exclusao",
                "cobertura",
                "dias_validos",
                "observacoes_medias",
                "proporcao_preco_parado",
            ]
        ],
        tables_dir / "excluded_tickers.csv",
    )
    save_csv(
        coverage.loc[coverage["status"].eq("included"), ["ticker", "grupo"]],
        processed_dir / "selected_tickers.csv",
    )
    LOGGER.info(
        "Amostra final: %d incluidos de %d candidatos",
        len(included),
        len(coverage),
    )
    return coverage, selected


# ==============================================================================
# BLOCO INTEGRADO DE jumps.py
# ==============================================================================

def jump_variation(realized_variance: float, bipower_variation: float) -> float:
    """JV = max(RV - BV, 0), preservando NaN quando necessario."""
    if not np.isfinite(realized_variance) or not np.isfinite(bipower_variation):
        return float("nan")
    return float(max(realized_variance - bipower_variation, 0.0))


def jump_test_statistic(
    realized_variance: float,
    bipower_variation: float,
    tripower_quarticity: float,
    observations: int,
) -> float:
    """Calcula a estatistica padronizada do teste de jump."""
    if (
        observations < 3
        or not np.isfinite(realized_variance)
        or not np.isfinite(bipower_variation)
        or not np.isfinite(tripower_quarticity)
        or realized_variance <= 0
        or bipower_variation <= 0
    ):
        return float("nan")

    variance_constant = (pi / 2) ** 2 + pi - 5
    quarticity_ratio = max(
        1.0,
        tripower_quarticity / (bipower_variation**2),
    )
    denominator = sqrt(
        variance_constant * (1 / observations) * quarticity_ratio
    )
    if denominator <= 0 or not np.isfinite(denominator):
        return float("nan")
    return float(
        ((realized_variance - bipower_variation) / realized_variance)
        / denominator
    )


def jump_test(
    realized_variance: float,
    bipower_variation: float,
    tripower_quarticity: float,
    observations: int,
    alpha: float = 0.99,
) -> dict[str, Any]:
    """Classifica jump day e documenta casos numericamente instaveis."""
    if not 0.5 < alpha < 1:
        raise ValueError("alpha deve estar entre 0.5 e 1")
    critical_value = float(norm.ppf(alpha))
    statistic = jump_test_statistic(
        realized_variance,
        bipower_variation,
        tripower_quarticity,
        observations,
    )
    if not np.isfinite(statistic):
        return {
            "jump_z": np.nan,
            "critical_value": critical_value,
            "jump_day": False,
            "status": "insufficient_or_unstable",
        }
    return {
        "jump_z": statistic,
        "critical_value": critical_value,
        "jump_day": bool(statistic > critical_value),
        "status": "ok",
    }


# ==============================================================================
# BLOCO INTEGRADO DE realized_measures.py
# ==============================================================================

def _finite_returns(returns: Iterable[float]) -> np.ndarray:
    values = np.asarray(list(returns), dtype=float)
    return values[np.isfinite(values)]


def mu_p(power: float) -> float:
    """Momento absoluto de ordem p de uma normal padrao."""
    return 2 ** (power / 2) * gamma((power + 1) / 2) / gamma(0.5)


def realized_variance(returns: Iterable[float]) -> float:
    """RV = soma dos quadrados dos retornos intradiarios."""
    values = _finite_returns(returns)
    return float(np.square(values).sum())


def realized_volatility(returns: Iterable[float]) -> float:
    """RVol diaria = raiz quadrada da RV."""
    return sqrt(realized_variance(returns))


def bipower_variation(returns: Iterable[float]) -> float:
    """Calcula a bipower variation diaria com correcao de amostra."""
    values = _finite_returns(returns)
    observations = len(values)
    if observations < 2:
        return float("nan")
    adjacent_products = np.abs(values[1:]) * np.abs(values[:-1])
    mu_1 = sqrt(2 / pi)
    return float(
        mu_1 ** -2
        * (observations / (observations - 1))
        * adjacent_products.sum()
    )


def tripower_quarticity(returns: Iterable[float]) -> float:
    """Calcula tripower quarticity com potencia 4/3."""
    values = _finite_returns(returns)
    observations = len(values)
    if observations < 3:
        return float("nan")
    powered = np.abs(values) ** (4 / 3)
    triple_products = powered[:-2] * powered[1:-1] * powered[2:]
    return float(
        observations
        * mu_p(4 / 3) ** -3
        * (observations / (observations - 2))
        * triple_products.sum()
    )


def compute_daily_measures(
    intraday: pd.DataFrame,
    annualization_days: int = 252,
    jump_alpha: float = 0.99,
    min_observations: int = 40,
) -> pd.DataFrame:
    """Agrega retornos intradiarios em medidas por ticker-dia."""
    rows: list[dict[str, Any]] = []
    data = intraday.copy()
    data["date"] = pd.to_datetime(data["date"], errors="coerce")

    for (ticker, date), group in data.groupby(["ticker", "date"], sort=True):
        returns = _finite_returns(group["log_return"])
        observations = len(returns)
        if observations < min_observations:
            continue
        rv = realized_variance(returns)
        bv = bipower_variation(returns)
        tq = tripower_quarticity(returns)
        jv = jump_variation(rv, bv)
        test = jump_test(rv, bv, tq, observations, jump_alpha)
        rows.append(
            {
                "ticker": ticker,
                "date": date,
                "n_intraday_returns": observations,
                "rv": rv,
                "rvol_daily": sqrt(rv),
                "rvol_annualized": sqrt(annualization_days * rv),
                "bv": bv,
                "tq": tq,
                "jv": jv,
                "jump_share": jv / rv if rv > 0 else np.nan,
                "jump_z": test["jump_z"],
                "jump_critical_value": test["critical_value"],
                "jump_day": test["jump_day"],
                "jump_test_status": test["status"],
            }
        )
    return pd.DataFrame(rows)


def run_realized_measures(
    config: dict[str, Any] | None = None,
) -> pd.DataFrame:
    """Calcula e salva as medidas realizadas."""
    config = config or load_config()
    intraday = pd.read_csv(
        PROJECT_ROOT / "data" / "processed" / "intraday_returns.csv",
        parse_dates=["datetime", "date"],
    )
    settings = config["volatility"]
    measures = compute_daily_measures(
        intraday,
        annualization_days=settings["annualization_days"],
        jump_alpha=settings["jump_test_alpha"],
        min_observations=settings["min_intraday_obs_per_day"],
    )
    save_csv(
        measures,
        PROJECT_ROOT / "data" / "processed" / "realized_measures.csv",
    )
    return measures


# ==============================================================================
# BLOCO INTEGRADO DE garch_models.py
# ==============================================================================

def _parameter(params: pd.Series, prefix: str) -> float:
    matches = [name for name in params.index if str(name).startswith(prefix)]
    return float(params[matches[0]]) if matches else np.nan


def estimate_garch_for_ticker(
    ticker_data: pd.DataFrame,
    measures: pd.DataFrame,
    ticker: str,
    settings: dict[str, Any],
) -> tuple[dict[str, Any], pd.DataFrame]:
    """Ajusta um GARCH e retorna resumo e serie condicional."""
    returns = (
        ticker_data[["date", "daily_return_pct"]]
        .dropna()
        .sort_values("date")
        .copy()
    )
    observations = len(returns)
    if observations < settings["min_daily_observations"]:
        return (
            {
                "ticker": ticker,
                "omega": np.nan,
                "alpha": np.nan,
                "beta": np.nan,
                "alpha_plus_beta": np.nan,
                "log_likelihood": np.nan,
                "aic": np.nan,
                "bic": np.nan,
                "correlation_garch_realized": np.nan,
                "observations_used": observations,
                "fit_status": "insufficient_observations",
            },
            pd.DataFrame(),
        )

    try:
        from arch import arch_model

        model = arch_model(
            returns["daily_return_pct"],
            mean="Constant",
            vol="GARCH",
            p=settings["p"],
            q=settings["q"],
            dist=settings["distribution"],
            rescale=False,
        )
        result = model.fit(disp="off", show_warning=False)
        params = result.params
        alpha = _parameter(params, "alpha[")
        beta = _parameter(params, "beta[")
        series = returns.copy()
        series["ticker"] = ticker
        series["garch_vol_daily"] = (
            np.asarray(result.conditional_volatility, dtype=float) / 100
        )
        comparison = series.merge(
            measures.loc[
                measures["ticker"].eq(ticker),
                ["date", "rvol_daily"],
            ],
            on="date",
            how="left",
        )
        correlation = comparison[
            ["garch_vol_daily", "rvol_daily"]
        ].corr().iloc[0, 1]
        summary = {
            "ticker": ticker,
            "omega": float(params.get("omega", np.nan)),
            "alpha": alpha,
            "beta": beta,
            "alpha_plus_beta": alpha + beta,
            "log_likelihood": float(result.loglikelihood),
            "aic": float(result.aic),
            "bic": float(result.bic),
            "correlation_garch_realized": float(correlation),
            "observations_used": observations,
            "fit_status": (
                "ok" if bool(result.convergence_flag == 0) else "not_converged"
            ),
        }
        return summary, comparison
    except Exception as exc:  # noqa: BLE001
        LOGGER.exception("Falha no GARCH de %s", ticker)
        return (
            {
                "ticker": ticker,
                "omega": np.nan,
                "alpha": np.nan,
                "beta": np.nan,
                "alpha_plus_beta": np.nan,
                "log_likelihood": np.nan,
                "aic": np.nan,
                "bic": np.nan,
                "correlation_garch_realized": np.nan,
                "observations_used": observations,
                "fit_status": f"failed: {exc}",
            },
            pd.DataFrame(),
        )


def run_garch_models(
    config: dict[str, Any] | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Estima GARCH para todos os ativos selecionados."""
    config = config or load_config()
    daily = pd.read_csv(
        PROJECT_ROOT / "data" / "processed" / "daily_prices_returns.csv",
        parse_dates=["date"],
    )
    measures = pd.read_csv(
        PROJECT_ROOT / "data" / "processed" / "realized_measures.csv",
        parse_dates=["date"],
    )
    summaries: list[dict[str, Any]] = []
    series_parts: list[pd.DataFrame] = []
    for ticker, ticker_data in daily.groupby("ticker", sort=True):
        summary, series = estimate_garch_for_ticker(
            ticker_data,
            measures,
            ticker,
            config["garch"],
        )
        summaries.append(summary)
        if not series.empty:
            series_parts.append(series)

    summary_frame = pd.DataFrame(summaries)
    series_frame = (
        pd.concat(series_parts, ignore_index=True)
        if series_parts
        else pd.DataFrame(
            columns=[
                "date",
                "daily_return_pct",
                "ticker",
                "garch_vol_daily",
                "rvol_daily",
            ]
        )
    )
    save_csv(
        summary_frame,
        PROJECT_ROOT / "outputs" / "tables" / "garch_summary.csv",
    )
    save_csv(
        series_frame,
        PROJECT_ROOT / "data" / "processed" / "garch_volatility.csv",
    )
    return summary_frame, series_frame


# ==============================================================================
# BLOCO INTEGRADO DE event_analysis.py
# ==============================================================================

def load_manual_events(path: Path) -> pd.DataFrame:
    """Le eventos manuais; cabecalho vazio e um caso valido."""
    if not path.exists():
        return pd.DataFrame(
            columns=["ticker", "date", "event_type", "event_description"]
        )
    try:
        events = pd.read_csv(path)
    except pd.errors.EmptyDataError:
        return pd.DataFrame(
            columns=["ticker", "date", "event_type", "event_description"]
        )
    required = {"ticker", "date", "event_type", "event_description"}
    if not required.issubset(events.columns):
        raise ValueError(
            f"events_earnings.csv deve conter: {sorted(required)}"
        )
    events = events.dropna(subset=["ticker", "date"]).copy()
    events["date"] = pd.to_datetime(events["date"], errors="coerce").dt.normalize()
    return events.dropna(subset=["date"])


def analyze_event_windows(
    events: pd.DataFrame,
    measures: pd.DataFrame,
) -> pd.DataFrame:
    """Compara t-1, t e t+1 com dias normais do mesmo ticker."""
    if events.empty or measures.empty:
        return pd.DataFrame(columns=EVENT_COLUMNS)

    data = measures.copy()
    data["date"] = pd.to_datetime(data["date"]).dt.normalize()
    rows: list[dict[str, Any]] = []

    for event in events.itertuples(index=False):
        ticker_data = (
            data.loc[data["ticker"].eq(event.ticker)]
            .sort_values("date")
            .reset_index(drop=True)
        )
        positions = ticker_data.index[ticker_data["date"].eq(event.date)].tolist()
        if not positions:
            rows.append(
                {
                    "ticker": event.ticker,
                    "event_date": event.date,
                    "event_type": event.event_type,
                    "event_description": event.event_description,
                    "status": "event_date_not_in_sample",
                }
            )
            continue

        position = positions[0]
        window_positions = [position - 1, position, position + 1]
        window = ticker_data.loc[
            [p for p in window_positions if 0 <= p < len(ticker_data)]
        ]
        normal = ticker_data.drop(
            index=[p for p in window_positions if 0 <= p < len(ticker_data)]
        )

        def value_at(offset: int, column: str) -> Any:
            target = position + offset
            if not 0 <= target < len(ticker_data):
                return np.nan
            return ticker_data.loc[target, column]

        normal_mean = float(normal["rvol_daily"].mean()) if not normal.empty else np.nan
        window_mean = float(window["rvol_daily"].mean())
        rows.append(
            {
                "ticker": event.ticker,
                "event_date": event.date,
                "event_type": event.event_type,
                "event_description": event.event_description,
                "rvol_t_minus_1": value_at(-1, "rvol_daily"),
                "rvol_t": value_at(0, "rvol_daily"),
                "rvol_t_plus_1": value_at(1, "rvol_daily"),
                "jump_day_t_minus_1": value_at(-1, "jump_day"),
                "jump_day_t": value_at(0, "jump_day"),
                "jump_day_t_plus_1": value_at(1, "jump_day"),
                "normal_mean_rvol": normal_mean,
                "event_window_mean_rvol": window_mean,
                "event_vs_normal_ratio": (
                    window_mean / normal_mean
                    if np.isfinite(normal_mean) and normal_mean > 0
                    else np.nan
                ),
                "normal_jump_frequency": (
                    float(normal["jump_day"].mean()) if not normal.empty else np.nan
                ),
                "event_window_jump_frequency": float(window["jump_day"].mean()),
                "status": "ok",
            }
        )
    return pd.DataFrame(rows).reindex(columns=EVENT_COLUMNS)


def _plot_event_summary(summary: pd.DataFrame, path: Path) -> None:
    plt.close("all")
    figure, axis = plt.subplots(figsize=(10, 5.5))
    valid = summary.loc[summary["status"].eq("ok")].copy()
    if valid.empty:
        axis.text(
            0.5,
            0.5,
            "Nenhum evento manual preenchido ou presente na amostra.",
            ha="center",
            va="center",
            fontsize=13,
        )
        axis.set_axis_off()
    else:
        positions = np.arange(len(valid))
        width = 0.36
        axis.bar(
            positions - width / 2,
            100 * valid["normal_mean_rvol"],
            width,
            label="Dias normais",
            color="#4C78A8",
        )
        axis.bar(
            positions + width / 2,
            100 * valid["event_window_mean_rvol"],
            width,
            label="Janela t-1 a t+1",
            color="#E45756",
        )
        axis.set_xticks(positions)
        axis.set_xticklabels(
            valid["ticker"] + "\n" + valid["event_date"].astype(str),
            rotation=30,
            ha="right",
        )
        axis.set_ylabel("Volatilidade realizada diaria (%)")
        axis.legend(frameon=False)
        axis.grid(axis="y", alpha=0.25)
    axis.set_title("Volatilidade em janelas de divulgacao de resultados")
    figure.tight_layout()
    path.parent.mkdir(parents=True, exist_ok=True)
    figure.savefig(path, dpi=220, bbox_inches="tight")
    plt.close(figure)


def run_event_analysis(
    config: dict[str, Any] | None = None,
) -> pd.DataFrame:
    """Executa a etapa opcional sem interromper a pipeline vazia."""
    config = config or load_config()
    events_path = PROJECT_ROOT / "data" / "manual" / "events_earnings.csv"
    measures_path = PROJECT_ROOT / "data" / "processed" / "realized_measures.csv"
    events = load_manual_events(events_path)
    measures = (
        pd.read_csv(measures_path, parse_dates=["date"])
        if measures_path.exists()
        else pd.DataFrame()
    )
    summary = analyze_event_windows(events, measures)
    save_csv(
        summary,
        PROJECT_ROOT / "outputs" / "tables" / "event_window_summary.csv",
    )
    _plot_event_summary(
        summary,
        PROJECT_ROOT / "outputs" / "figures" / "event_window_volatility.png",
    )
    LOGGER.info("Eventos manuais validos analisados: %d", len(summary))
    return summary


